import { Group, PlaneGeometry, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { position, rotation, scale } = config.scenePosition || { position: { x: 0, y: 1.6, z: 0 }, rotation: { x: 0, y: 0, z: 0 }, scale: { x: 1, y: 1, z: 1 } };
  const { ink, paper, accent, surface } = config.colors || {};
  const textureUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const texture = ctx.textureLoader.load(textureUrl);

  // Plane size based on atlas region aspect (512x320)
  const planeWidth = 0.6;
  const planeHeight = planeWidth * (320 / 512); // ~0.375

  // Main badge plane
  const badgeGeom = new PlaneGeometry(planeWidth, planeHeight);
  const badgeMat = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    alphaTest: 0.1
  });
  // Optional: tint the texture with accent? Not specified, keep as-is.
  const badgeMesh = new Mesh(badgeGeom, badgeMat);

  // Accent edge border mesh (slightly larger, hidden initially)
  const borderWidth = planeWidth + 0.04;
  const borderHeight = planeHeight + 0.04;
  const borderGeom = new PlaneGeometry(borderWidth, borderHeight);
  const borderMat = new MeshBasicNodeMaterial({
    color: accent || '#ff2a38',
    transparent: true,
    opacity: 0,
    side: 2 // DoubleSide
  });
  const borderMesh = new Mesh(borderGeom, borderMat);
  borderMesh.position.z = -0.001; // slightly behind to avoid z-fighting

  const group = new Group();
  group.add(badgeMesh);
  group.add(borderMesh);

  // Apply scene placement
  group.position.set(position.x, position.y, position.z);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.set(scale.x, scale.y, scale.z);

  // Store original Y for hover lift
  let originalY = group.position.y;

  // Data bindings (store for engine reference)
  group.userData.dataBindings = config.dataBindings || [];

  // Event handlers
  group.userData.handlers = {
    hover: () => {
      // Subtle lift: rise-in preset (y +0.15)
      gsap.to(group.position, {
        y: originalY + 0.15,
        duration: 0.3,
        ease: 'power3.out',
        overwrite: 'auto'
      });
      // Show accent edge
      gsap.to(borderMat, {
        opacity: 0.8,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    },
    unhover: () => {
      gsap.to(group.position, {
        y: originalY,
        duration: 0.3,
        ease: 'power3.out',
        overwrite: 'auto'
      });
      gsap.to(borderMat, {
        opacity: 0,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    },
    click: () => {
      // Emit event: hub-collection.select
      // The engine should read this; we set a property
      group.userData.eventEmit = 'hub-collection.select';
      // Optional press-down effect
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out(1)',
        yoyo: true,
        repeat: 1
      });
    }
  };

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill GSAP timelines on this group
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(borderMat);

    // Dispose geometries
    badgeGeom.dispose();
    borderGeom.dispose();

    // Dispose materials
    badgeMat.dispose();
    borderMat.dispose();

    // Dispose texture (if not shared, but we assume texture is shared via loader)
    texture.dispose();
  };

  return group;
}
